'use strict';
(()=>{
 const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>new Intl.NumberFormat('de-AT',{style:'currency',currency:'EUR',maximumFractionDigits:2}).format(n),labels={all:'Beide Camper',both:'Beide Camper',egon:'Camper Egon',elio:'Camper Elio',offen:'Offen','in-arbeit':'In Arbeit',freigabe:'Zur Freigabe',erledigt:'Erledigt',einzahlung:'Einzahlung',geplant:'Geplant',bestellt:'Bestellt',bezahlt:'Bezahlt'};
 let decisionFilter='offen';let driveStatus=null,cloudUploads=new Map();const LOCAL_LIMIT=10*1024*1024;
 let bank=null,bankError='',bankLoading=false;let fileCategory='all';let pendingFiles=[],uploadPurchase='';
 let actor,state,page='Start',vehicle='all',editing=null,users=[];let busy=false,mailboxMessages=[],mailboxError='',mailboxLoading=false,mailboxTime='',mailFolder='inbox',cloudDetail=null,loginTimer=null;

 const localDate=()=>{const d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');};
 const typeLabels={task:'Aufgabe',appointment:'Termin',decision:'Entscheidung',note:'Notiz / Idee'};
 const entryTypes=(r,kind='tasks')=>r.types||[kind==='decisions'?'decision':'task'];
 const entries=()=>[...state.tasks.map(r=>({...r,_kind:'tasks'})),...state.decisions.map(r=>({...r,_kind:'decisions'}))];
 const safeLink=value=>{try{const u=new URL(value);return ['https:','http:'].includes(u.protocol)?u.href:'';}catch{return '';}};
 const deepLink=(kind,id)=>location.origin+'/camper/#'+kind+'/'+encodeURIComponent(id);
 const wa=(r,kind)=>'<a class="share-link" target="_blank" rel="noopener noreferrer" href="https://wa.me/?text='+encodeURIComponent(labels[r.vehicle]+' · Bitte um Rückmeldung: '+r.title+(r.date?' · bis '+r.date:'')+'\n'+deepLink(kind,r.id))+'">Über WhatsApp teilen ↗</a>';
 const linkedFiles=id=>state.files.filter(f=>f.purchaseId===id).map(file).join('');
 function ideaCard(r){const f=state.files.find(f=>f.id===r.fileId),url=safeLink(r.url),img=f?.type.startsWith('image/')?'/camper/api/files/'+f.id:safeLink(r.imageUrl);return '<article class="panel idea-card">'+(f?.storage==='onedrive'||f?.previewDisk?cloudPreview(f):f?.type.startsWith('video/')?'<video class="idea-image" controls preload="metadata" src="/camper/api/files/'+f.id+'"></video>':img?'<img class="idea-image" loading="lazy" referrerpolicy="no-referrer" src="'+esc(img)+'" alt="">':'<div class="idea-placeholder">💡 Inspiration</div>')+'<h3>'+esc(r.title)+'</h3>'+tags(r)+'<p>'+esc(r.topic)+'</p><p>'+esc(r.notes)+'</p><div class="actions">'+(url?'<a target="_blank" rel="noopener noreferrer" href="'+esc(url)+'">Original-Link öffnen ↗</a>':'')+(f?'<a href="/camper/api/files/'+f.id+'?download=1">Original herunterladen</a><button data-preview-add="'+f.id+'">Vorschaubild hinzufügen</button>':'')+'<button data-edit="ideas" data-id="'+r.id+'">Bearbeiten</button><button data-from-idea="'+r.id+'" data-target="tasks">Aufgabe / Entscheidung</button><button data-from-idea="'+r.id+'" data-target="purchases">Anfrage erstellen</button>'+wa(r,'ideas')+'</div></article>';}
 function purchaseCard(r){return '<article class="panel"><h3>'+esc(r.title)+'</h3>'+tags(r)+'<p><strong>'+({anfrage:'Anfrage',angebot:'Angebot',bestellung:'Auftrag / Bestellung',rechnung:'Rechnung'}[r.stage]||'Anfrage')+'</strong> · '+esc(r.supplier)+' · '+money(r.amount)+'</p><p>Rechnung: '+({offen:'Offen',teilbezahlt:'Teilweise bezahlt',bezahlt:'Bezahlt'}[r.payment]||'Offen')+' · bezahlt '+money(r.paidAmount||0)+(r.dueDate?' · fällig '+esc(r.dueDate):'')+'</p><p>'+esc(r.notes)+'</p><div class="actions"><button data-edit="purchases" data-id="'+r.id+'">Vorgang öffnen</button><button data-purchase-upload="'+r.id+'">Beleg hinzufügen</button>'+wa(r,'purchases')+'</div><div class="file-grid">'+linkedFiles(r.id)+'</div></article>';}
 function resolveLink(){const match=location.hash.match(/^#(tasks|decisions|ideas|purchases)\/([^/]+)$/);if(!match)return;const kind=match[1],row=state[kind].find(r=>r.id===decodeURIComponent(match[2]));if(!row){message('Der verlinkte Eintrag ist nicht mehr vorhanden.',true);return;}page={tasks:'Aufgaben',decisions:'Entscheidungen',ideas:'Ideen & Inspiration',purchases:'Budget & Einkauf'}[kind];vehicle='all';$('#vehicle').value='all';render();openEditor(kind,row);}


 function optionsForCategories(){return [['all','Alle Anlagen'],...Object.entries(categoryLabels).filter(([k])=>!['mail','idee'].includes(k))].map(([k,v])=>'<option value="'+k+'" '+(fileCategory===k?'selected':'')+'>'+v+'</option>').join('');}
 const categoryLabels={idee:'Ideen',plan:'Pläne',angebot:'Angebote',rechnung:'Rechnungen',sonstiges:'Sonstiges',mail:'Mail'};
 const attachmentUrl=(mid,aid)=>'/camper/api/mailbox/messages/'+encodeURIComponent(mid)+'/attachments/'+encodeURIComponent(aid);
 function organizeFile(row,attachment){editing={kind:attachment?'import-attachment':'file',row,attachment};$('#edit-form').innerHTML='<h2>'+ (attachment?'Mail-Anhang ablegen':'Datei verschieben')+'</h2><p>'+esc(row.name)+'</p><label>Ablage<select name="category">'+Object.entries(categoryLabels).filter(([k])=>!['mail','idee'].includes(k)).map(([k,v])=>'<option value="'+k+'" '+(row.category===k?'selected':'')+'>'+v+'</option>').join('')+'</select></label><label>Camper<select name="vehicle">'+options(['both','egon','elio'],row.vehicle||(vehicle==='all'?'both':vehicle))+'</select></label><label>Zu Einkaufsvorgang (optional)<select name="purchaseId"><option value="">Kein Vorgang</option>'+state.purchases.map(p=>'<option value="'+p.id+'" '+(row.purchaseId===p.id?'selected':'')+'>'+esc(p.title)+' · '+esc(labels[p.vehicle])+'</option>').join('')+'</select></label><p class="muted">'+(attachment?'Der Anhang wird in der Camperwerkstatt gespeichert. Das Original bleibt in der Mail.':'Die Datei erhält die gewählte Ablage; der Inhalt bleibt erhalten.')+'</p><div class="actions"><button type="submit" class="primary">Ablegen</button><button type="button" data-close>Abbrechen</button></div>';if(!$('#editor').open)$('#editor').showModal();}

 function message(text,error=false){$('#message').textContent=text;$('#message').className=error?'error':'';const dialog=$('#editor');if(dialog?.open){let status=$('#editor-status');if(!status){status=document.createElement('p');status.id='editor-status';status.setAttribute('aria-live','polite');const form=$('#edit-form');form.insertBefore(status,form.querySelector('.actions'));}status.textContent=text;status.className='editor-status'+(error?' error':'');status.setAttribute('role',error?'alert':'status');}}

 async function api(url,opts={}){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),opts.raw?120000:45000);try{const res=await fetch('/camper/api/'+url,{...opts,signal:opts.signal||controller.signal,headers:{...(opts.body&&!opts.raw?{'Content-Type':'application/json'}:{}),...opts.headers},body:opts.body&&!opts.raw?JSON.stringify(opts.body):opts.body});const data=await res.json().catch(()=>({error:'Serverantwort konnte nicht gelesen werden.'}));if(!res.ok)throw Error(data.error||'Zugriff nicht möglich.');return data;}catch(e){if(e.name==='AbortError')throw Error('Der Server antwortet gerade nicht. Bitte zuerst prüfen, ob der Eintrag bereits gespeichert wurde, bevor du nochmals speicherst.');if(e.message==='Failed to fetch'||e.message==='fetch failed')throw Error('Verbindung unterbrochen. Bitte prüfen, ob der Eintrag bereits gespeichert wurde. Deine Eingaben bleiben hier erhalten.');throw e;}finally{clearTimeout(timer);}}

 const filtered=rows=>rows.filter(r=>vehicle==='all'||r.vehicle===vehicle||r.vehicle==='both');
 const share=r=>vehicle==='all'?r.amount:r.vehicle==='both'?r.amount/2:r.amount;
 const tags=r=>`<span class="pill vehicle-badge vehicle-${r.vehicle}">${labels[r.vehicle]}</span>${r.status?`<span class="pill">${labels[r.status]}</span>`:''}${r.person?`<span class="pill">${esc(r.person)}</span>`:''}${r.date?`<span class="pill">${esc(r.date)}${r.time?' · '+esc(r.time):''}</span>`:''}`;
 function rows(kind){return filtered(state[kind]||[]);}function summary(){const costs=rows('costs'),purchases=rows('purchases'),pshare=(r,n)=>vehicle!=='all'&&r.vehicle==='both'?n/2:n,sum=status=>costs.filter(r=>r.status===status).reduce((n,r)=>n+share(r),0);const budget=vehicle==='all'?state.budget.egon+state.budget.elio:state.budget[vehicle];return {budget,paid:sum('bezahlt')+purchases.reduce((n,r)=>n+pshare(r,r.paidAmount||0),0),ordered:sum('bestellt')+purchases.filter(r=>['bestellung','rechnung'].includes(r.stage)).reduce((n,r)=>n+pshare(r,r.amount-(r.paidAmount||0)),0),planned:sum('geplant')+purchases.filter(r=>['anfrage','angebot'].includes(r.stage)).reduce((n,r)=>n+pshare(r,r.amount-(r.paidAmount||0)),0),deposits:sum('einzahlung'),get free(){return this.budget-this.paid-this.ordered;}};}
 const metrics=()=>{const s=summary();return `<div class="metrics">${[['Budget',s.budget],['Bezahlt',s.paid],['Offen bestellt',s.ordered],['Noch frei',s.free]].map(([k,v])=>`<div class="metric"><span class="muted">${k}</span><strong>${money(v)}</strong></div>`).join('')}</div>`;};
 function heading(title,action,button){return `<div class="heading"><h2>${title}</h2>${button?`<button class="primary" data-action="${action}">${button}</button>`:''}</div>`;}
 const item=(r,kind)=>`<div class="row"><div class="row-top"><strong>${esc(r.title)}</strong><div class="row-buttons"><button data-edit="${kind}" data-id="${r.id}">Bearbeiten</button>${kind==='tasks'?`<button data-copy="${r.id}">Kopieren & ändern</button>`:''}</div></div>${tags(r)}${['tasks','decisions'].includes(kind)?entryTypes(r,kind).map(t=>`<span class="pill">${typeLabels[t]}</span>`).join('')+wa(r,kind):''}${r.amount?`<p>${kind==='hours'?esc(r.amount)+' h':money(r.amount)}</p>`:''}${r.notes?`<p>${esc(r.notes)}</p>`:''}<small class="muted">${esc(r.by)}</small></div>`;
 const file=r=>`<article class="panel plan-card">${r.previewDisk||r.storage==='onedrive'?cloudPreview(r):['image/jpeg','image/png','image/webp'].includes(r.type)?`<button class="plan-thumb" data-view="${r.id}" aria-label="${esc(r.name)} ansehen"><img loading="lazy" src="/camper/api/files/${r.id}" alt="${esc(r.name)}"></button>`:r.type==='application/pdf'?`<div class="pdf-thumb"><iframe loading="lazy" tabindex="-1" title="Vorschau ${esc(r.name)}" src="/camper/api/files/${r.id}#toolbar=0&navpanes=0"></iframe><button data-view="${r.id}" aria-label="${esc(r.name)} ansehen">PDF öffnen</button></div>`:`<div class="file-placeholder">${r.name.toLowerCase().endsWith('.skp')?'◇ SketchUp · 3D':'📎 Anlage'}</div>`}<h3>${esc(r.name)}</h3>${tags(r)}${r.storage==='onedrive'?'<span class="pill">☁ OneDrive · '+(r.size/1024/1024).toFixed(1)+' MB</span>':''}<span class="pill">${categoryLabels[r.category]||'Pläne'}</span><p class="muted">${esc(r.versionLabel||'Planstand nicht bezeichnet')} · ${new Date(r.created).toLocaleDateString('de-AT')} · ${esc(r.by)}</p><div class="actions">${['image/jpeg','image/png','application/pdf'].includes(r.type)?`<button data-view="${r.id}">Ansehen</button>`:''}${r.modelUrl?`<a href="${esc(r.modelUrl)}" target="_blank" rel="noopener noreferrer">3D ansehen ↗</a>`:''}<a href="/camper/api/files/${r.id}?download=1">Original herunterladen</a><button data-organize-file="${r.id}">Verschieben / zuordnen</button><button data-preview-add="${r.id}">Vorschaubild hinzufügen</button></div>${r.name.toLowerCase().endsWith('.skp')&&!r.modelUrl?'<p class="muted">Für die 3D-Ansicht einen SketchUp-/Trimble-Link beim Upload hinterlegen.</p>':''}</article>`;



 async function embeddedPng(file){
 const signature=[137,80,78,71,13,10,26,10],block=4*1024*1024,cap=Math.min(file.size,64*1024*1024);
 for(let offset=0;offset<cap;offset+=block){const bytes=new Uint8Array(await file.slice(offset,Math.min(offset+block+8,file.size)).arrayBuffer());for(let i=0;i<bytes.length-8;i++){if(bytes[i]!==137||!signature.every((v,j)=>bytes[i+j]===v))continue;const start=offset+i,scan=new Uint8Array(await file.slice(start,Math.min(start+8*1024*1024,file.size)).arrayBuffer()),view=new DataView(scan.buffer);let p=8,valid=false;while(p+12<=scan.length){const len=view.getUint32(p),type=String.fromCharCode(...scan.subarray(p+4,p+8));if(len>8*1024*1024||p+12+len>scan.length)break;if(p===8){if(type!=='IHDR'||len!==13)break;const width=view.getUint32(p+8),height=view.getUint32(p+12);if(!width||!height||width*height>4000000)break;}if(type==='IDAT')valid=true;p+=12+len;if(type==='IEND'&&len===0&&valid)return new Blob([scan.subarray(0,p)],{type:'image/png'});}}}return null;
 }
 async function autoPreviewBlob(file){
 if(/\.skp$/i.test(file.name))return embeddedPng(file);
 if(!/\.(jpg|jpeg|png|webp|mp4|webm|mov)$/i.test(file.name))return null;
 const url=URL.createObjectURL(file);let image;
 try{if(/\.(mp4|webm|mov)$/i.test(file.name)){image=document.createElement('video');image.muted=true;image.preload='metadata';await new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(Error('Video-Vorschau dauert zu lange.')),12000);image.onloadeddata=()=>{clearTimeout(timer);resolve();};image.onerror=()=>{clearTimeout(timer);reject(Error('Video-Vorschau nicht verfügbar.'));};image.src=url;});}else{image=new Image();image.src=url;await image.decode();}
 const width=image.videoWidth||image.naturalWidth,height=image.videoHeight||image.naturalHeight;if(!width||!height)return null;const scale=Math.min(480/width,320/height,1),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(width*scale));canvas.height=Math.max(1,Math.round(height*scale));canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);return await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.8));
 }finally{if(image?.tagName==='VIDEO'){image.removeAttribute('src');image.load();}URL.revokeObjectURL(url);}
 }
 async function attachAutoPreview(file,record){try{if(!record)return;const preview=await autoPreviewBlob(file);if(preview)state=await api('files/'+record.id+'/preview',{method:'POST',raw:true,headers:{'Content-Type':'application/octet-stream'},body:preview});}catch{/* The original is already safely stored; OneDrive thumbnail remains the fallback. */}}

 function driveNotice(){return '<section class="panel drive-notice"><strong>Automatische Dateiablage</strong><p>Bis 10 MB in der Camperwerkstatt · über 10 MB in OneDrive unter Camperwerkstatt / Camper / Ablage. Link und Vorschau bleiben hier als Kachel.</p><p>'+esc(driveStatus?.connected?'OneDrive verbunden':driveStatus?.error||'OneDrive-Verbindung wird geprüft …')+'</p>'+(actor.admin?(driveStatus?.connected?'<button data-drive-prepare>'+(driveStatus.folderReady?'Projektordner prüfen':'Projektordner vorbereiten')+'</button><button data-drive-refresh>Verbindung prüfen</button>':'<button data-drive-connect>OneDrive verbinden / freigeben</button><div id="ms-login"></div>'):'')+'</section>';}
 async function loadDrive(){try{driveStatus=await api('onedrive/status');}catch(e){driveStatus={connected:false,error:e.message};}}
 function cloudPreview(r){return '<a class="plan-thumb cloud-thumb" target="_blank" rel="noopener noreferrer" href="/camper/api/files/'+r.id+'"><span>☁ OneDrive · '+esc(r.name.split('.').pop().toUpperCase())+'</span><img class="cloud-preview-image" loading="lazy" src="/camper/api/files/'+r.id+(r.previewDisk?'/preview':'/cloud-thumbnail')+'?v='+(r.version||1)+'" alt="Vorschau '+esc(r.name)+'"></a>';}
 async function uploadCloud(file,b){
 let pending=cloudUploads.get(file);
 if(!pending){const data=await api('onedrive/uploads',{method:'POST',body:{name:file.name,size:file.size,vehicle:b.vehicle,category:b.category,version:b.version,modelUrl:b.modelUrl,purchaseId:b.purchaseId||uploadPurchase}});pending={...data,offset:0};cloudUploads.set(file,pending);}
 if(pending.failed){try{state=await api('onedrive/uploads/'+pending.id+'/complete',{method:'POST',body:{itemId:pending.itemId}});await attachAutoPreview(file,state.files.find(f=>f.id===pending.id));cloudUploads.delete(file);return state;}catch{}const status=await fetch(pending.uploadUrl,{credentials:'omit'});if(status.status===404||status.status===410){cloudUploads.delete(file);throw Error('OneDrive-Upload abgelaufen. Bitte Speichern erneut wählen, um neu zu beginnen.');}if(!status.ok)throw Error('Uploadstatus nicht erreichbar. Bitte Speichern erneut wählen.');const data=await status.json();pending.offset=Number(data.nextExpectedRanges?.[0]?.split('-')[0]||0);pending.failed=false;}
 try{
 while(pending.offset<file.size){const start=pending.offset,end=Math.min(start+10*1024*1024,file.size);message('OneDrive: '+file.name+' · '+Math.floor(start/file.size*100)+' % – bitte dieses Fenster offen lassen.');
 const response=await fetch(pending.uploadUrl,{method:'PUT',credentials:'omit',headers:{'Content-Range':'bytes '+start+'-'+(end-1)+'/'+file.size,'Content-Type':'application/octet-stream'},body:file.slice(start,end)});
 if(!response.ok)throw Error(response.status===507?'OneDrive hat nicht genügend Speicher.':'OneDrive-Upload unterbrochen (HTTP '+response.status+'). Bitte Speichern erneut wählen.');
 const result=await response.json();if(response.status===200||response.status===201){pending.itemId=result.id;pending.offset=file.size;break;}const next=Number(result.nextExpectedRanges?.[0]?.split('-')[0]);if(!Number.isSafeInteger(next)||next<end||next>file.size)throw Error('OneDrive hat keinen gültigen Uploadfortschritt bestätigt.');pending.offset=next;
 }
 let uploadedState=await api('onedrive/uploads/'+pending.id+'/complete',{method:'POST',body:{itemId:pending.itemId}});state=uploadedState;await attachAutoPreview(file,state.files.find(f=>f.id===pending.id));cloudUploads.delete(file);return state;
 }catch(e){pending.failed=true;throw Error(e.message==='Failed to fetch'?'OneDrive-Verbindung unterbrochen. Bitte Speichern erneut wählen; der Upload kann fortgesetzt werden.':e.message);}
 }
 document.addEventListener('error',e=>{if(e.target.classList?.contains('cloud-preview-image'))e.target.hidden=true;},true);
 document.addEventListener('change',async e=>{if(e.target.id!=='preview-upload'||!e.target.files.length)return;const input=e.target,file=input.files[0];try{if(file.size>LOCAL_LIMIT)throw Error('Vorschaubild bitte kleiner als 10 MB wählen.');message('Vorschaubild wird gespeichert …');state=await api('files/'+input.dataset.fileId+'/preview',{method:'POST',raw:true,headers:{'Content-Type':'application/octet-stream'},body:file});render();message('Vorschaubild gespeichert.');}catch(err){message(err.message,true);}finally{input.value='';}});

 function bankCard(){return '<article class="panel bank-card"><div class="heading"><h3>Revolut Business · MAN TGE</h3><button data-bank-refresh>Aktualisieren</button></div>'+(bank?.account?'<strong class="bank-amount">'+esc(new Intl.NumberFormat('de-AT',{style:'currency',currency:bank.account.currency}).format(Number(bank.account.balance)))+'</strong><p>'+esc(bank.account.name)+' · '+(bank.stale?'Letzter bekannter Stand':'Abgerufen')+': '+esc(new Date(bank.fetchedAt).toLocaleString('de-AT'))+'</p>':'<p>'+esc(bankError||(bankLoading?'Kontostand wird abgerufen …':'TGE-Konto noch nicht zugeordnet.'))+'</p>')+(bankError&&bank?.account?'<p class="error">'+esc(bankError)+'</p>':'')+(actor.admin&&bank?.accounts?.length?'<details><summary>TGE-Konto zuordnen</summary><select id="bank-account"><option value="">Bitte wählen</option>'+bank.accounts.map(a=>'<option value="'+esc(a.id)+'" '+(bank.account?.id===a.id?'selected':'')+'>'+esc(a.name)+' · '+esc(a.currency)+'</option>').join('')+'</select><button data-bank-save>Zuordnung speichern</button></details>':'')+'<p class="muted">Teil des Firmen-Gesamtsaldos · keine zusätzliche Buchung im Budget.</p></article>';}
 async function loadBank(){if(bankLoading)return;bankLoading=true;bankError='';try{bank=await api('bank-balance');}catch(e){bankError=e.message;if(bank)bank.stale=true;}finally{bankLoading=false;}}
 function decisionCell(r,who,key,type='text'){const field=key+who,value=r[field]??(key==='person'?r.person:key==='due'?r.date:key==='decisionStatus'?(r['answer'+who]?'entschieden':'offen'):'')??'';const attrs=' data-decision="'+r.id+'" data-kind="'+r._kind+'" data-field="'+field+'" aria-label="'+esc(key+' '+who)+'"';return type==='select'?'<select'+attrs+'>'+['offen','entschieden','vertagt'].map(v=>'<option value="'+v+'" '+(v===value?'selected':'')+'>'+v+'</option>').join('')+'</select>':type==='textarea'?'<textarea'+attrs+'>'+esc(value)+'</textarea>':'<input type="'+type+'"'+attrs+' value="'+esc(value)+'">';}

 function decisionRecord(r,who){let at=r['answeredAt'+who]||'',by=r['answeredBy'+who]||'';if(!at&&r['answer'+who]){const history=r.history||[];for(let i=history.length-1;i>=0;i--){const after=history[i+1]?.before||r;if(String(history[i].before['answer'+who]||'')!==String(after['answer'+who]||'')){at=history[i].at;by=history[i].by;break;}}}return at?'Erfasst von '+esc(by||'Unbekannt')+' · '+esc(new Date(at).toLocaleString('de-AT')):r['answer'+who]?'Erfassungszeit bisher nicht gespeichert':'Noch keine Entscheidung';}


 function decisionChoice(r,w){const value=r['choice'+w]||'',old=!!r['answer'+w]&&!value;return '<select data-decision="'+r.id+'" data-kind="'+r._kind+'" data-field="choice'+w+'" aria-label="Entscheidung '+w+'"><option value="">'+(old?'Bisherige Antwort':'Offen')+'</option><option value="ja" '+(value==='ja'?'selected':'')+'>Ja</option><option value="nein" '+(value==='nein'?'selected':'')+'>Nein</option></select>';}
 function decisionTable(){const list=filtered(entries()).filter(r=>entryTypes(r,r._kind).includes('decision'));let count=0;const body=list.flatMap(r=>(r.vehicle==='both'?['Egon','Elio']:[r.vehicle==='egon'?'Egon':'Elio']).filter(w=>vehicle==='all'||w.toLowerCase()===vehicle).filter(w=>decisionFilter==='alle'||(!r['choice'+w]&&!String(r['answer'+w]||'').trim())).map(w=>{count++;return '<tr><td><input type="date" data-decision="'+r.id+'" data-kind="'+r._kind+'" data-field="askedDate" value="'+esc(r.askedDate||r.created?.slice(0,10)||'')+'"></td><td><span class="pill vehicle-badge vehicle-'+w.toLowerCase()+'">'+w+'</span></td><td><textarea data-decision="'+r.id+'" data-kind="'+r._kind+'" data-field="title">'+esc(r.title)+'</textarea></td><td>'+decisionCell(r,w,'person')+'</td><td>'+decisionCell(r,w,'due','date')+'</td><td>'+decisionChoice(r,w)+'</td><td>'+decisionCell(r,w,'answer','textarea')+'<small class="decision-record">'+decisionRecord(r,w)+'</small></td><td>'+decisionCell(r,w,'decided','date')+(!r['decided'+w]&&r['answer'+w]?'<small>Entscheidungsdatum fehlt</small>':'')+'</td><td><button data-edit="'+r._kind+'" data-id="'+r.id+'">Öffnen</button>'+wa(r,r._kind)+'<button data-history="'+r.id+'" data-kind="'+r._kind+'">Verlauf</button></td></tr>';})).join('');return '<label>Ansicht<select id="decision-filter"><option value="offen" '+(decisionFilter==='offen'?'selected':'')+'>Offene Entscheidungen</option><option value="alle" '+(decisionFilter==='alle'?'selected':'')+'>Alle Entscheidungen</option></select></label><p class="hint">Eine Zeile pro Entscheidung und Camper · Offen / Ja / Nein direkt auswählen. Datum und Bearbeiter werden beim Antworten erfasst.</p><div class="decision-scroll"><table class="decision-table"><thead><tr>'+['Frage vom','Camper','Frage / Entscheidung','Wer entscheidet?','Frist','Offen / Ja / Nein','Details / Ergebnis','Entschieden am','Verknüpfung'].map(t=>'<th scope="col">'+t+'</th>').join('')+'</tr></thead><tbody>'+body+'</tbody></table></div>'+(!count?'<p>Keine offenen Entscheidungen in dieser Ansicht.</p>':'');}

 function showHistory(id,kind){const r=state[kind].find(r=>r.id===id);$('#preview').innerHTML='<h2>Änderungsverlauf · '+esc(r.title)+'</h2>'+((r.history||[]).slice().reverse().map(h=>'<article class="row"><strong>'+esc(h.by)+' · '+esc(new Date(h.at).toLocaleString('de-AT'))+'</strong><p>Frage vom '+esc(h.before.askedDate||h.before.created?.slice(0,10)||'')+' · Vorher: '+esc(h.before.title)+'</p>'+['Egon','Elio'].map(w=>'<p>'+w+': '+esc(h.before['answer'+w]||'Noch keine Antwort')+' · '+esc(h.before['person'+w]||h.before.person||'')+' · Frist '+esc(h.before['due'+w]||h.before.date||'')+' · '+esc(h.before['decisionStatus'+w]||'offen')+' · entschieden '+esc(h.before['decided'+w]||'')+'</p>').join('')+'</article>').join('')||'<p>Noch keine Änderungen.</p>');$('#viewer').showModal();}
 let decisionQueue=Promise.resolve();
 document.addEventListener('change',e=>{const el=e.target;if(!el.dataset.decision)return;const value=el.value,id=el.dataset.decision,kind=el.dataset.kind,key=el.dataset.field;el.disabled=true;decisionQueue=decisionQueue.catch(()=>{}).then(async()=>{const row=state[kind].find(r=>r.id===id);const {history,...current}=row;const body={...current,[key]:value};if(key.startsWith('choice')){const who=key.slice(6);if(!value){body['answer'+who]='';body['decided'+who]='';body['decisionStatus'+who]='offen';}}if(key.startsWith('answer')&&value.trim()){const who=key.slice(6);body['decisionStatus'+who]='entschieden';body['decided'+who]=body['decided'+who]||localDate();}try{state=await api('items/'+kind+'/'+id,{method:'PATCH',body});const saved=state[kind].find(r=>r.id===id);document.querySelectorAll('[data-decision]').forEach(input=>{if(input.dataset.decision===id&&input!==document.activeElement){const f=input.dataset.field;if(saved[f]!==undefined)input.value=saved[f];}});message('Entscheidung gespeichert.');el.classList.add('saved');if(key.startsWith('choice'))render();}catch(err){message(err.message,true);el.value=row[key]||'';if(err.message.includes('inzwischen'))await load();}finally{el.disabled=false;}});});

 function render(){const main=$('#main');$('#nav').innerHTML=['Start','Aufgaben','Pläne & Dateien','Budget & Einkauf','Stunden','Mails','Entscheidungen','Termine','Ideen & Inspiration',...(actor.admin?['Zugänge']:[])].map(n=>`<button aria-current="${page===n}" data-page="${n}">${n}</button>`).join('');
 if(page==='Start'){main.innerHTML=heading('Euer gemeinsamer Ausbau')+bankCard()+`<div class="grid">${['egon','elio'].filter(v=>vehicle==='all'||vehicle===v).map(v=>`<article class="panel"><h3>${labels[v]}</h3><p>${state.tasks.filter(r=>r.vehicle===v||r.vehicle==='both').filter(r=>r.status!=='erledigt').length} offene Aufgaben</p><button data-vehicle="${v}">Fahrzeug öffnen</button></article>`).join('')}<article class="panel full"><h3>${labels[vehicle]} · Budget</h3>${metrics()}</article><article class="panel"><h3>Als Nächstes</h3>${rows('tasks').filter(r=>r.status!=='erledigt').sort((a,b)=>(a.date||'z').localeCompare(b.date||'z')).slice(0,4).map(r=>item(r,'tasks')).join('')||'<p class="muted">Noch keine Aufgaben. Beginnt mit eurer Arbeitsliste.</p>'}</article><article class="panel"><h3>Neue Pläne & Unterlagen</h3>${rows('files').slice(-4).reverse().map(r=>`<div class="row">${esc(r.name)}<br><span class="muted">${esc(r.by)} · ${esc(r.versionLabel)}</span></div>`).join('')||'<p class="muted">Noch keine Dateien hochgeladen.</p>'}</article></div>`;}
 else if(page==='Aufgaben'){main.innerHTML=heading('Aufgaben','tasks','+ Aufgabe')+`<div class="board">${['offen','in-arbeit','freigabe','erledigt'].map(status=>`<section class="lane"><h3>${labels[status]}</h3>${filtered(entries()).filter(r=>r.status===status).map(r=>`<article class="task"><strong>${esc(r.title)}</strong><div>${tags(r)}</div><div class="row-buttons"><button data-edit="${r._kind||'tasks'}" data-id="${r.id}">Öffnen</button><button data-copy="${r.id}" data-kind="${r._kind||'tasks'}">Kopieren & ändern</button>${wa(r,r._kind||'tasks')}</div></article>`).join('')||'<p class="muted">Keine Aufgaben</p>'}</section>`).join('')}</div>`;}
 else if(page==='Pläne & Dateien'){main.innerHTML=heading('Pläne & Dateien','upload','+ Datei / Planstand')+driveNotice()+'<div id="plan-drop" class="drop-zone" tabindex="0" role="button" aria-label="Pläne hochladen">Anlagen hier hineinziehen – Pläne, Angebote oder Rechnungen<br><button data-action="upload">Dateien auswählen</button></div><p class="hint">JPEG, PNG und PDF direkt ansehen. SketchUp: Originaldatei plus Link zur 3D-Ansicht. Neue Planstände separat hochladen, damit ältere erhalten bleiben.</p><div class="file-grid">'+'<label>Ablage<select id="file-category">'+optionsForCategories()+'</select></label>'+rows('files').filter(r=>r.category!=='mail'&&r.category!=='idee'&&(fileCategory==='all'||(r.category||'plan')===fileCategory)).slice().reverse().map(file).join('')+'</div>';}
 else if(page==='Budget & Einkauf'){const s=summary();main.innerHTML=heading('Budget & Einkauf','purchases','+ Anfrage / Einkauf')+bankCard()+`<article class="panel">${metrics()}<p class="muted">Zusätzlich geplant: ${money(s.planned)} · Eingezahlt: ${money(s.deposits)}</p><p class="muted">„Noch frei“ = Budget − bezahlt − offen bestellt. Gemeinsame Kosten werden je Fahrzeug zur Hälfte gerechnet.</p><button data-action="budget">Budgets festlegen</button></article><div class="actions"><button data-action="costs">+ Sonstiger Betrag / Einzahlung</button></div><p class="hint">Anfrage → Angebot → Auftrag / Bestellung → Rechnung · Ein Vorgang zählt einmal im Budget.</p><div class="file-grid">${rows('purchases').slice().reverse().map(purchaseCard).join('')}</div><article class="panel" style="margin-top:18px">${rows('costs').slice().reverse().map(r=>item(r,'costs')).join('')||'<p>Noch keine Kosten erfasst.</p>'}</article><p class="muted">Kontostand und Einkaufsbudget werden getrennt angezeigt. Der TGE-Saldo bleibt im Firmen-Gesamtsaldo enthalten.</p>`;}
 else if(page==='Stunden'){const total=rows('hours').reduce((n,r)=>n+share(r),0);main.innerHTML=heading('Stunden & Aufwand','hours','+ Stunden')+`<p>Gesamt: <strong>${total.toLocaleString('de-AT')} h</strong> · Gemeinsame Stunden werden je Fahrzeug hälftig gerechnet.</p><article class="panel">${rows('hours').slice().reverse().map(r=>item(r,'hours')).join('')||'<p>Noch keine Stunden erfasst.</p>'}</article>`;}
 else if(page==='Mails'){main.innerHTML=heading('Projektmails · man@krista.at')+`<div id="plan-drop" class="drop-zone" tabindex="0" role="button" aria-label="Anlagen hochladen">Anlagen vom PC hier hineinziehen<br><button data-action="upload">Dateien auswählen / ablegen</button></div><section class="panel"><div class="heading"><h3>Gemeinsames Postfach</h3><div class="actions"><button data-compose>Neue Mail</button><button data-mail-refresh>Neu laden</button></div></div><p class="muted">Microsoft 365 · 50 neueste Mails je Ordner · gemeinsames Postfach für beide Camper</p><div class="actions"><button data-mail-folder="inbox">Posteingang</button><button data-mail-folder="sentitems">Gesendet</button>${actor.admin?'<button data-ms-connect>Verbinden / Senderecht</button>':''}</div><div id="ms-login"></div><div id="mailbox-panel"></div></section><details style="margin-top:20px"><summary>Eigene Mailnotizen & hochgeladene EML</summary><div class="actions"><button data-action="mails">+ Mailnotiz</button><button data-action="upload-mail">+ EML hochladen</button></div><article class="panel" style="margin-top:18px">${rows('mails').slice().reverse().map(r=>item(r,'mails')).join('')||'<p>Noch keine Mailnotizen.</p>'}</article><div class="file-grid" style="margin-top:18px">${rows('files').filter(r=>r.category==='mail').map(file).join('')}</div></details>`;renderMailbox();}

 else if(page==='Entscheidungen'){main.innerHTML=heading('Entscheidungsprotokoll','decisions','+ Frage / Entscheidung')+decisionTable();}
 else if(page==='Termine'){const type=page==='Termine'?'appointment':'decision';main.innerHTML=heading(page,type==='decision'?'decisions':'appointment','+ '+(type==='decision'?'Entscheidung':'Termin'))+'<article class="panel">'+filtered(entries()).filter(r=>entryTypes(r,r._kind).includes(type)).sort((a,b)=>(a.date||'z').localeCompare(b.date||'z')).map(r=>item(r,r._kind)).join('')+'</article>';}
 else if(page==='Ideen & Inspiration')main.innerHTML=heading('Ideen & Inspiration','ideas','+ Idee / Link')+driveNotice()+'<div id="idea-drop" class="drop-zone" tabindex="0" role="button" aria-label="Ideen hinzufügen">Bilder und Videos hier hineinziehen – auch Instagram- und Webseiten-Links<br><button data-action="upload-idea">Dateien auswählen</button></div><p>Ein Upload wird als eigene Ideen-Kachel gespeichert. Links öffnen das Original.</p><div class="file-grid">'+rows('ideas').slice().reverse().map(ideaCard).join('')+'</div>';
 else if(page==='Zugänge')main.innerHTML=heading('Camper-Zugänge','user','+ Benutzer anlegen')+`<article class="panel"><p>Diese Benutzer erhalten ausschließlich Zugang zur Camperwerkstatt.</p>${users.map(u=>`<div class="row row-top"><span><strong>${esc(u.name)}</strong><br>${esc(u.login)} · ${u.disabled?'Gesperrt':'Aktiv'}</span><button data-user="${u.id}" data-disabled="${u.disabled?'false':'true'}">${u.disabled?'Aktivieren':'Sperren'}</button></div>`).join('')||'<p class="muted">Noch keine Camper-Benutzer angelegt.</p>'}</article>`;
 }
 function renderMailbox(){const panel=$('#mailbox-panel');if(!panel)return;panel.innerHTML=mailboxLoading?'<p>Postfach wird abgerufen …</p>':mailboxError?`<p class="hint">${esc(mailboxError)}</p>${actor.admin?'<p><a href="/kristine#planning">Microsoft-Verbindung in KRISTINE öffnen</a></p>':''}`:`${mailboxTime?`<p class="muted">Abgerufen: ${esc(mailboxTime)}</p>`:''}${mailboxMessages.map(m=>`<div class="row"><div class="row-top"><div><strong>${esc(m.subject)}</strong><p>${esc(m.from.name||m.from.email)} · ${m.receivedAt?esc(new Date(m.receivedAt).toLocaleString('de-AT')):''}</p><p class="muted">${esc(m.preview.slice(0,180))}</p>${m.hasAttachments?'<span class="pill">Mit Anhängen</span>':''}</div><button data-cloudmail="${esc(m.id)}">Öffnen</button></div></div>`).join('')||'<p>Keine Mails im Posteingang.</p>'}`;}
 async function loadMailbox(){if(mailboxLoading)return;mailboxLoading=true;mailboxError='';renderMailbox();try{const result=await api('mailbox/messages?folder='+mailFolder);mailboxMessages=result.messages;mailboxTime=new Date().toLocaleString('de-AT');}catch(e){mailboxError=e.message;}finally{mailboxLoading=false;renderMailbox();}}
 async function openCloudMail(id){message('Mail wird geöffnet …');const m=await api('mailbox/messages/'+encodeURIComponent(id));cloudDetail=m;$('#preview').innerHTML=`<h2>${esc(m.subject)}</h2><button data-reply>Antworten</button><p><strong>Von:</strong> ${esc(m.from.name)} &lt;${esc(m.from.email)}&gt;</p><p><strong>An:</strong> ${esc(m.to.map(p=>p.email).join(', '))}</p>${m.cc.length?`<p><strong>CC:</strong> ${esc(m.cc.map(p=>p.email).join(', '))}</p>`:''}<p class="mail-body">${esc(m.body)}</p>${m.attachments.length?'<h3>Anhänge</h3>':''}${m.attachments.map((a,index)=>`<article class="row"><strong>${esc(a.name)}</strong> · ${Math.ceil(a.size/1024)} KB<div class="actions"><a target="_blank" rel="noopener noreferrer" href="${attachmentUrl(m.id,a.id)}">Öffnen / herunterladen ↗</a><button data-preview-attachment="${index}">Vorschau</button><button data-import-attachment="${index}">Ablegen in …</button></div></article>`).join('')}`;$('#viewer').showModal();message('');}
 async function connectMicrosoft(forDrive=false){const r=await fetch('/kristine/api/outlook/login/start',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({camperMailSend:true,camperDrive:forDrive})});const d=await r.json();if(!r.ok)throw Error(d.error||'Microsoft-Verbindung konnte nicht gestartet werden.');const panel=$('#ms-login');if(!panel)return;panel.innerHTML=`<div class="hint"><p>Mit <strong>alexander.krista@krista.at</strong> anmelden und die Microsoft-Freigabe bestätigen.</p><p>Code: <strong>${esc(d.userCode)}</strong></p><a href="https://microsoft.com/devicelogin" target="_blank" rel="noopener noreferrer">Microsoft-Anmeldung öffnen ↗</a><p>${forDrive?'Für die Dateiablage die Microsoft-Freigabe für OneDrive bestätigen. Dateien über 10 MB werden im Ordner Camperwerkstatt gespeichert.':'Für man@krista.at benötigt Alexander zusätzlich Lesezugriff und „Senden als“.'}</p><p id="ms-login-state">Warte auf die Anmeldung …</p></div>`;if(loginTimer)clearInterval(loginTimer);const end=Date.now()+Math.min(Number(d.expiresIn||900),900)*1000;let checking=false;loginTimer=setInterval(async()=>{if(checking)return;if(Date.now()>end){clearInterval(loginTimer);if($('#ms-login-state'))$('#ms-login-state').textContent='Code abgelaufen. Bitte erneut verbinden.';return;}checking=true;try{const r=await fetch('/kristine/api/outlook/login/poll',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({sessionId:d.sessionId})});const p=await r.json();if(p.status==='connected'){clearInterval(loginTimer);if($('#ms-login-state'))$('#ms-login-state').textContent='Microsoft verbunden. Postfach wird geprüft …';if(forDrive){await loadDrive();render();message(driveStatus?.connected?'OneDrive ist verbunden.':driveStatus?.error||'Bitte Verbindung prüfen.',!driveStatus?.connected);}else await loadMailbox();}else if(!r.ok){clearInterval(loginTimer);if($('#ms-login-state'))$('#ms-login-state').textContent=p.error||'Anmeldung fehlgeschlagen.';}}catch(e){message(e.message,true);}finally{checking=false;}},Math.max(5,Number(d.interval||5))*1000);}
 function openCompose(reply){if($('#viewer').open)$('#viewer').close();editing={kind:'send',replyId:reply?.id||'',requestId:crypto.randomUUID()};const to=reply?(reply.replyTo.length?reply.replyTo:[reply.from]).map(p=>p.email).join(', '):'';$('#edit-form').innerHTML=`<h2>${reply?'Antworten':'Neue Mail'}</h2><p>Absender: <strong>man@krista.at</strong></p><label>An (mehrere mit Komma)<input name="to" type="text" value="${esc(to)}" ${reply?'readonly':'required'}></label>${reply?'':'<label>CC<input name="cc" type="text"></label>'}<label>Betreff<input name="subject" required maxlength="300" value="${reply?esc(/^re:/i.test(reply.subject)?reply.subject:'Re: '+reply.subject):''}" ${reply?'readonly':''}></label><label>Nachricht<textarea name="text" required style="min-height:180px"></textarea></label><label>Anhänge vom Gerät (zusammen max. 2 MB)<input type="file" name="sendFiles" multiple></label><label>Projektdateien anhängen<select name="projectFiles" multiple>${state.files.filter(f=>f.storage!=='onedrive').map(f=>`<option value="${f.id}">${esc(f.name)}</option>`).join('')}</select></label><div class="actions"><button class="primary" type="submit">Von man@krista.at senden</button><button type="button" data-close>Abbrechen</button></div>`;$('#editor').showModal();}
 async function sendComposer(form,b){const files=Array.from(form.elements.sendFiles.files);if(files.reduce((n,f)=>n+f.size,0)>2*1024*1024)throw Error('Anhänge zusammen maximal 2 MB.');const attachments=await Promise.all(files.map(file=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=()=>reject(Error('Anhang konnte nicht gelesen werden.'));reader.onload=()=>resolve({name:file.name,contentBytes:String(reader.result).split(',')[1]});reader.readAsDataURL(file);})));await api('mailbox/send',{method:'POST',body:{to:b.to,cc:b.cc,subject:b.subject,text:b.text,replyId:editing.replyId,requestId:editing.requestId,attachments,projectFiles:Array.from(form.elements.projectFiles.selectedOptions).map(o=>o.value)}});$('#editor').close();mailFolder='sentitems';message('An Microsoft zum Versand übergeben.');await loadMailbox();}
 function options(vals,selected){return vals.map(v=>`<option value="${v}" ${v===selected?'selected':''}>${labels[v]||v}</option>`).join('');}
 function field(name,label,value='',type='text',required=false){return `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${type==='number'?'min="0.01" step="0.01"':''}></label>`;}
 function openEditor(kind,row,copy=false){const appointment=kind==='appointment';if(appointment)kind='tasks';editing={kind,row:copy?null:row};let html='';if(kind==='user')html='<h2>Camper-Zugang anlegen</h2>'+field('name','Name','','text',true)+field('login','Benutzername','','text',true)+field('password','Passwort (mindestens 12 Zeichen)','','password',true);else if(kind==='budget')html='<h2>Budget festlegen</h2>'+field('egon','Budget Egon (€)',state.budget.egon,'number',true)+field('elio','Budget Elio (€)',state.budget.elio,'number',true);else {const upload=kind.startsWith('upload');html=`<h2>${upload?'Datei hochladen':copy===true?'Aufgabe kopieren & ändern':row?'Eintrag bearbeiten':'Neuer Eintrag'}</h2><label>Fahrzeug<select name="vehicle">${options(['both','egon','elio'],(copy===true&&row?.vehicle==='egon'?'elio':copy&&row?.vehicle==='elio'?'egon':row?.vehicle)||(vehicle==='all'?'both':vehicle))}</select></label>`;if(upload)html+=`<label>Datei · über 10 MB automatisch nach OneDrive<input name="file" type="file" multiple accept="${kind==='upload-mail'?'.eml':kind==='upload-idea'?'.jpg,.jpeg,.png,.webp,.pdf,.mp4,.webm,.mov,.zip':'.jpg,.jpeg,.png,.webp,.pdf,.skp,.zip'}" ${pendingFiles.length?'':'required'}></label>${pendingFiles.length?`<p>${pendingFiles.map(f=>esc(f.name)).join('<br>')}</p>`:''}`+'<label>Ablage<select name="category">'+Object.entries(categoryLabels).filter(([k])=>kind==='upload-mail'?k==='mail':kind==='upload-idea'?k==='idee':!['mail','idee'].includes(k)).map(([k,v])=>'<option value="'+k+'" '+((kind==='upload-idea'&&k==='idee')||(kind==='upload-mail'&&k==='mail')?'selected':'')+'>'+v+'</option>').join('')+'</select></label><label>Einkaufsvorgang (optional)<select name="purchaseId"><option value="">Kein Vorgang</option>'+state.purchases.map(p=>'<option value="'+p.id+'" '+(uploadPurchase===p.id?'selected':'')+'>'+esc(p.title)+'</option>').join('')+'</select></label>'+field('version','Planstand / Version')+field('modelUrl','SketchUp-/Trimble-Link zur 3D-Ansicht','','url');else{html+=field('title',kind==='mails'?'Betreff':'Bezeichnung',row?.title,'text',true);if(['tasks','decisions','costs'].includes(kind))html+=`<label>Status<select name="status">${options(kind==='costs'?['geplant','bestellt','bezahlt','einzahlung']:['offen','in-arbeit','freigabe','erledigt'],copy?'offen':row?.status)}</select></label>`;if(['costs','hours'].includes(kind))html+=field('amount',kind==='hours'?'Stunden':'Betrag (€)',row?.amount,'number',true);
if(['tasks','decisions'].includes(kind)){
const types=appointment?['appointment']:entryTypes(row||{},kind);
html+=field('askedDate','Frage gestellt am',row?.askedDate||row?.created?.slice(0,10)||localDate(),'date');
for(const who of ['Egon','Elio']){html+='<label>Entscheidung '+who+'<select name="choice'+who+'"><option value="">Offen / bisherige Antwort</option><option value="ja" '+(row?.['choice'+who]==='ja'?'selected':'')+'>Ja</option><option value="nein" '+(row?.['choice'+who]==='nein'?'selected':'')+'>Nein</option></select></label>';html+=field('person'+who,'Entscheidet für '+who,row?.['person'+who]||row?.person)+field('due'+who,'Frist '+who,row?.['due'+who]||row?.date,'date')+field('decided'+who,'Entschieden am · '+who,row?.['decided'+who],'date')+'<label>Status '+who+'<select name="decisionStatus'+who+'">'+['offen','entschieden','vertagt'].map(v=>'<option value="'+v+'" '+((row?.['decisionStatus'+who]||(row?.['answer'+who]?'entschieden':'offen'))===v?'selected':'')+'>'+v+'</option>').join('')+'</select></label>';}
html+='<fieldset><legend>Art des Eintrags · Mehrfachauswahl</legend>'+Object.entries(typeLabels).map(([t,label])=>'<label class="check"><input type="checkbox" name="types" value="'+t+'" '+(types.includes(t)?'checked':'')+'>'+label+'</label>').join('')+'</fieldset>'+field('time','Uhrzeit (bei Termin erforderlich)',row?.time,'time')+
'<p class="muted">Bei einer neuen oder geänderten Antwort werden Erfassungszeit, Bearbeiter und Entscheidungsdatum automatisch gespeichert.</p><label>Antwort / Ergebnis Egon<textarea name="answerEgon">'+esc(copy?'':row?.answerEgon||'')+'</textarea></label><label>Antwort / Ergebnis Elio<textarea name="answerElio">'+esc(copy?'':row?.answerElio||'')+'</textarea></label>';
}
if(kind==='ideas')html+='<input type="hidden" name="fileId" value="'+esc(row?.fileId||'')+'">'+field('url','Video / Instagram / Webseite',row?.url,'url')+field('imageUrl','Vorschaubild (Bild-Link, optional)',row?.imageUrl,'url')+field('topic','Thema, z. B. Küche, Bad, Elektrik',row?.topic);
if(kind==='purchases')html+='<label>Stand<select name="stage">'+Object.entries({anfrage:'Anfrage',angebot:'Angebot',bestellung:'Auftrag / Bestellung',rechnung:'Rechnung'}).map(([v,t])=>'<option value="'+v+'" '+(row?.stage===v?'selected':'')+'>'+t+'</option>').join('')+'</select></label>'+field('supplier','Lieferant',row?.supplier)+field('amount','Gesamtbetrag (€)',row?.amount||0,'number',true)+field('paidAmount','Bereits bezahlt (€)',row?.paidAmount||0,'number',true)+field('invoiceDate','Rechnungsdatum',row?.invoiceDate,'date')+field('dueDate','Fälligkeit',row?.dueDate,'date')+field('paidDate','Zahlungsdatum',row?.paidDate,'date')+'<p class="muted">Offen / teilweise bezahlt / bezahlt ergibt sich aus Gesamtbetrag und Zahlung.</p>';
if(['tasks','decisions','purchases'].includes(kind)&&row?.sourceIdea)html+='<input type="hidden" name="sourceIdea" value="'+esc(row.sourceIdea)+'"><p><a href="#ideas/'+encodeURIComponent(row.sourceIdea)+'">Ursprüngliche Idee öffnen</a></p>';
html+=field('person',kind==='mails'?'Absender':'Person / Zuständigkeit',row?.person)+field('date',kind==='tasks'||kind==='decisions'?'Termin':'Datum',row?.date,'date')+`<label>${kind==='mails'?'Mailtext':'Notizen / Details'}<textarea name="notes">${esc(row?.notes||'')}</textarea></label>`;}}
 if(row&&!copy)html+=wa(row,kind);html+='<div class="actions"><button class="primary" type="submit">Speichern</button><button type="button" data-close>Abbrechen</button>'+ (row&&!copy?'<button type="button" data-delete>Eintrag löschen</button>':'')+'</div>';$('#edit-form').innerHTML=html;if(['budget','purchases'].includes(kind))$('#edit-form').querySelectorAll('input[type=number]').forEach(el=>el.min=0);if(!$('#editor').open)$('#editor').showModal();message('');}
 async function load(){state=await api('state');if(actor.admin)users=await api('users');render();if(page==='Mails')await loadMailbox();}
 $('#login-form').onsubmit=async e=>{e.preventDefault();try{await api('login',{method:'POST',body:Object.fromEntries(new FormData(e.target))});await boot();message('');}catch(err){message(err.message,true);}};
 $('#vehicle').onchange=e=>{vehicle=e.target.value;render();};
 document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;try{if(b.hasAttribute('data-drive-prepare')){b.disabled=true;try{message('OneDrive-Projektordner wird vorbereitet …');await api('onedrive/prepare',{method:'POST',body:{}});await loadDrive();render();message('Projektordner Camperwerkstatt mit Egon, Elio und Beide Camper ist vorbereitet.');}finally{b.disabled=false;}}else if(b.hasAttribute('data-drive-refresh')){await loadDrive();render();}else if(b.hasAttribute('data-drive-connect')){await connectMicrosoft(true);}else if(b.dataset.previewAdd){const input=$('#preview-upload');input.dataset.fileId=b.dataset.previewAdd;input.click();}else if(b.hasAttribute('data-preview-attachment')){const att=cloudDetail.attachments[Number(b.dataset.previewAttachment)],url=attachmentUrl(cloudDetail.id,att.id);if(!/\.(pdf|png|jpe?g)$/i.test(att.name)){message('Diesen Dateityp bitte über Öffnen / herunterladen öffnen.');return;}$('#preview').innerHTML='<button data-back-mail>Zurück zur Mail</button><h2>'+esc(att.name)+'</h2>'+(/\.pdf$/i.test(att.name)?'<iframe title="Anhang" src="'+url+'"></iframe>':'<img alt="'+esc(att.name)+'" src="'+url+'">');}else if(b.hasAttribute('data-back-mail')){$('#viewer').close();await openCloudMail(cloudDetail.id);}else if(b.hasAttribute('data-import-attachment')){const att=cloudDetail.attachments[Number(b.dataset.importAttachment)];organizeFile(att,{messageId:cloudDetail.id,attachmentId:att.id});}else if(b.dataset.organizeFile){organizeFile(state.files.find(f=>f.id===b.dataset.organizeFile));}else if(b.hasAttribute('data-compose')){openCompose();}else if(b.hasAttribute('data-reply')){openCompose(cloudDetail);}else if(b.hasAttribute('data-ms-connect')){await connectMicrosoft();}else if(b.dataset.mailFolder){mailFolder=b.dataset.mailFolder;await loadMailbox();}else if(b.hasAttribute('data-mail-refresh')){await loadMailbox();}else if(b.dataset.cloudmail){await openCloudMail(b.dataset.cloudmail);}else if(b.dataset.page){page=b.dataset.page;render();if(page==='Mails')await loadMailbox();}else if(b.dataset.fromIdea){const idea=state.ideas.find(r=>r.id===b.dataset.fromIdea);if(!idea)throw Error('Idee fehlt.');openEditor(b.dataset.target,{title:idea.title,vehicle:idea.vehicle,notes:idea.notes+'\n'+(idea.url||''),sourceIdea:idea.id},'idea');}else if(b.dataset.purchaseUpload){pendingFiles=[];uploadPurchase=b.dataset.purchaseUpload;openEditor('upload');}else if(b.hasAttribute('data-history')){showHistory(b.dataset.history,b.dataset.kind);}else if(b.hasAttribute('data-bank-refresh')){await loadBank();render();}else if(b.hasAttribute('data-bank-save')){await api('bank-account',{method:'PUT',body:{id:$('#bank-account').value}});await loadBank();render();}else if(b.dataset.action){pendingFiles=[];uploadPurchase='';openEditor(b.dataset.action);}else if(b.dataset.copy){const source=state[b.dataset.kind||'tasks'].find(r=>r.id===b.dataset.copy);if(!source)throw Error('Aufgabe nicht mehr vorhanden. Bitte neu laden.');openEditor(b.dataset.kind||'tasks',source,true);}else if(b.dataset.edit)openEditor(b.dataset.edit,state[b.dataset.edit].find(r=>r.id===b.dataset.id));else if(b.dataset.vehicle){vehicle=b.dataset.vehicle;$('#vehicle').value=vehicle;page='Aufgaben';render();}else if(b.hasAttribute('data-close'))$('#editor').close();else if(b.hasAttribute('data-delete')){if(!confirm('Diesen Eintrag löschen?'))return;state=await api(`items/${editing.kind}/${editing.row.id}`,{method:'DELETE',body:{version:editing.row.version}});$('#editor').close();render();}else if(b.dataset.view){const r=state.files.find(r=>r.id===b.dataset.view);$('#preview').innerHTML=r.type==='application/pdf'?`<iframe title="${esc(r.name)}" src="/camper/api/files/${r.id}"></iframe><a target="_blank" rel="noopener" href="/camper/api/files/${r.id}">PDF separat öffnen</a>`:`<img alt="${esc(r.name)}" src="/camper/api/files/${r.id}">`;$('#viewer').showModal();}else if(b.id==='close-viewer'){$('#viewer').close();$('#preview').innerHTML='';}else if(b.dataset.user){await api('users/'+b.dataset.user,{method:'PATCH',body:{disabled:b.dataset.disabled==='true'}});await load();}else if(b.id==='logout'){await api('logout',{method:'POST'});location.reload();}}catch(err){message(err.message,true);}});
 $('#edit-form').onsubmit=async e=>{e.preventDefault();if(busy)return;busy=true;const submit=e.target.querySelector('[type=submit]');const submitLabel=submit.textContent;submit.disabled=true;submit.textContent='Wird gespeichert …';e.target.querySelectorAll('[data-close]').forEach(b=>b.disabled=true);message('Wird gespeichert … bitte warten.');const b=Object.fromEntries(new FormData(e.target)),{kind,row}=editing;try{if(kind==='file'||kind==='import-attachment'){if(kind==='file')state=await api('files/'+row.id,{method:'PATCH',body:{...b,version:row.version||1}});else{const at=editing.attachment;state=await api('mailbox/messages/'+encodeURIComponent(at.messageId)+'/attachments/'+encodeURIComponent(at.attachmentId)+'/import',{method:'POST',body:b});}$('#editor').close();render();message('Anlage abgelegt unter '+categoryLabels[b.category]+'.');return;}if(kind==='send'){await sendComposer(e.target,b);return;}if(kind==='user'){await api('users',{method:'POST',body:b});users=await api('users');}else if(kind==='budget')state=await api('budget',{method:'PUT',body:{egon:Number(b.egon),elio:Number(b.elio),revision:state.revision}});else if(kind.startsWith('upload')){
const files=pendingFiles.length?pendingFiles.slice():Array.from(e.target.elements.file.files);
if(!files.length)throw Error('Bitte Dateien auswählen.');
const invalid=files.find(f=>f.size>250*1024**3||!(kind==='upload-mail'?/\.eml$/i:kind==='upload-idea'?/\.(jpg|jpeg|png|webp|pdf|mp4|webm|mov|zip)$/i:/\.(jpg|jpeg|png|webp|pdf|skp|zip)$/i).test(f.name));
if(invalid)throw Error('Unzulässige Datei oder größer als 250 GB: '+invalid.name);
pendingFiles=files;
let count=0;
while(pendingFiles.length){const file=pendingFiles[0];message('Upload '+file.name+' …');
if(file.size>LOCAL_LIMIT){state=await uploadCloud(file,b);pendingFiles.shift();count++;continue;}
const q=new URLSearchParams({name:file.name,vehicle:b.vehicle,version:b.version,modelUrl:b.modelUrl,purchaseId:b.purchaseId||uploadPurchase,category:b.category||'plan'});
state=await api('files?'+q,{method:'POST',raw:true,headers:{'Content-Type':'application/octet-stream'},body:file});
await attachAutoPreview(file,state.files.at(-1));
pendingFiles.shift();count++;}
uploadPurchase='';
}else{if(['tasks','decisions'].includes(kind)){b.types=new FormData(e.target).getAll('types');if(!b.types.length)throw Error('Mindestens eine Eintragsart auswählen.');}if(b.amount)b.amount=Number(b.amount);if(row)b.version=row.version;state=await api('items/'+kind+(row?'/'+row.id:''),{method:row?'PATCH':'POST',body:b});}$('#editor').close();render();message('Gespeichert.');}catch(err){message(err.message,true);if(err.message.includes('inzwischen'))await load();}finally{busy=false;submit.disabled=false;submit.textContent=submitLabel;e.target.querySelectorAll('[data-close]').forEach(b=>b.disabled=false);}};
 $('#editor').addEventListener('cancel',e=>{if(busy)e.preventDefault();});
 async function boot(){try{actor=await api('me');$('#login').hidden=true;$('#app').hidden=false;$('#account').innerHTML=esc(actor.name)+(actor.admin?'':' <button id="logout">Abmelden</button>');await load();resolveLink();loadDrive().then(()=>{if(['Pläne & Dateien','Ideen & Inspiration'].includes(page)&&!$('#editor').open&&!document.activeElement?.matches('input,textarea,select'))render();});loadBank().then(()=>{if(['Start','Budget & Einkauf'].includes(page)&&!$('#editor').open&&!document.activeElement?.matches('input,textarea,select'))render();});}catch(err){$('#login').hidden=false;$('#app').hidden=true;message('Bitte mit deinem Camper-Zugang anmelden.');}}

 document.addEventListener('change',e=>{if(e.target.id==='decision-filter'){decisionFilter=e.target.value;render();}if(e.target.id==='file-category'){fileCategory=e.target.value;render();}});
 window.addEventListener('hashchange',()=>{if(actor&&state){if($('#editor').open)$('#editor').close();resolveLink();}});
 document.addEventListener('dragover',e=>{if(e.target.closest('#plan-drop, #idea-drop')){e.preventDefault();e.dataTransfer.dropEffect='copy';e.target.closest('#plan-drop, #idea-drop').classList.add('dragging');}});
 document.addEventListener('dragleave',e=>{e.target.closest('#plan-drop, #idea-drop')?.classList.remove('dragging');});
 document.addEventListener('drop',e=>{const zone=e.target.closest('#plan-drop, #idea-drop');if(!zone)return;e.preventDefault();zone.classList.remove('dragging');pendingFiles=Array.from(e.dataTransfer.files);uploadPurchase='';if(pendingFiles.length)openEditor(zone.id==='idea-drop'?'upload-idea':'upload');else if(zone.id==='idea-drop'){const link=(e.dataTransfer.getData('text/uri-list')||e.dataTransfer.getData('text/plain')).trim().split(/\r?\n/).find(x=>safeLink(x));if(link)openEditor('ideas',{title:'Neue Idee',url:link,vehicle:vehicle==='all'?'both':vehicle},'idea');}});
 document.addEventListener('keydown',e=>{if(['plan-drop','idea-drop'].includes(e.target.id)&&['Enter',' '].includes(e.key)){e.preventDefault();pendingFiles=[];uploadPurchase='';openEditor(e.target.id==='idea-drop'?'upload-idea':'upload');}});

 document.addEventListener('visibilitychange',()=>{if(!document.hidden&&actor&&!$('#editor').open)load().catch(e=>message(e.message,true));});setInterval(()=>{if(page==='Mails'&&!document.hidden&&!$('#editor').open&&!$('#viewer').open)loadMailbox();},60000);boot();
})();
